const text = $input.item.json.message.text;
const parts = text.split(' ');

return [{
  json: {
    applicant_id: parts[1],
    score: parseInt(parts[2]),
    chat_id: $input.item.json.message.chat.id
  }
}];

const text = $input.item.json.message.text;
const parts = text.split(' ');

return [{
  json: {
    applicant_id: parts[1],
    decision: parts[2].toLowerCase(),
    joining_date: parts[3] || '',
    chat_id: $input.item.json.message.chat.id
  }
}];

const items = $('Check Email Duplicate').all();

// 1 এর বেশি হলে duplicate
const isDuplicate = items.length > 1;

if (!isDuplicate) {
  // New applicant
  return $('Edit Fields').all();
} else {
  // Duplicate found
  return [{
    json: {
      duplicate: true,
      email: items[0].json['Email Address'],
      full_name: items[0].json['Full Name'],
      message: 'Duplicate application detected'
    }
  }];
}

